import sys
from collections import defaultdict

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    strings = input[1:]

    trie = defaultdict(dict)
    depths = []

    for s in strings:
        node = trie
        depth = 0
        for char in reversed(s):
            if char not in node:
                node[char] = {}
            node = node[char]
            depth += 1
        depths.append(depth)

    def dfs(node, depth):
        if not node:
            return depth
        max_depth = depth
        for child in node.values():
            max_depth = max(max_depth, dfs(child, depth + 1))
        return max_depth

    max_depth = dfs(trie, 0)
    count = depths.count(max_depth)

    print(count)

if __name__ == "__main__":
    main()
